INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L719_07','V719','阮明',7,'我会按时续借或者归还，避免产生逾期罚金。','wǒ huì àn shí xù jiè huò zhě guī huán， bì miǎn chǎn shēng yú qī fá jīn。','Em sẽ gia hạn hoặc trả sách đúng hạn, để tránh bị phạt trễ hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT720','SSH3','图书馆自习座位被占，咨询管理员占座管理规定',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V720','SIT720','P1','twist','ban_chinh_thuc',NULL,'图书馆严禁用书、水杯长期霸占自习座位，临时离开超过一小时管理员会清理占位物品，保障座位公平使用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_01','V720','阮明',1,'您好，这个自习座位放着书本一整天没人，我可以坐这里吗？','nín hǎo， zhè ge zì xí zuò wèi fàng zhe shū běn yī zhěng tiān méi rén， wǒ kě yǐ zuò zhè lǐ ma？','Chào anh/chị, chỗ tự học này để sách cả ngày không có ai ngồi, em ngồi đây được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_02','V720','管理员',2,'图书馆禁止长期占座，离开超过一小时物品会统一清收。','tú shū guǎn jìn zhǐ cháng qī zhàn zuò， lí kāi chāo guò yī xiǎo shí wù pǐn huì tǒng yī qīng shōu。','Thư viện cấm giữ chỗ lâu dài, rời chỗ quá một tiếng là đồ đạc sẽ bị thu gom hết đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_03','V720','阮明',3,'书本、水杯全都留在桌面，座位空了整整一下午嘛。','shū běn、 shuǐ bēi quán dōu liú zài zhuō miàn， zuò wèi kōng le zhěng zhěng yī xià wǔ ma。','Sách vở với cốc nước để nguyên trên bàn, chỗ trống suốt cả buổi chiều luôn mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_04','V720','管理员',4,'我先把占位物品收到失物存放区，你可以正常使用这个座位。','wǒ xiān bǎ zhàn wèi wù pǐn shōu dào shī wù cún fàng qū， nǐ kě yǐ zhèng cháng shǐ yòng zhè ge zuò wèi。','Để tôi mang đồ giữ chỗ đó cất vào khu đồ thất lạc trước, em cứ sử dụng chỗ ngồi này bình thường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_05','V720','阮明',5,'那物品主人回来，去哪里领取自己的书本、水杯？','nà wù pǐn zhǔ rén huí lái， qù nǎ lǐ lǐng qǔ zì jǐ de shū běn、 shuǐ bēi？','Vậy chủ nhân của đồ đó quay lại thì đến đâu để lấy lại sách vở, cốc nước ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_06','V720','管理员',6,'一楼服务台报姓名、物品特征就能取回存放物品。','yī lóu fú wù tái bào xìng míng、 wù pǐn tè zhēng jiù néng qǔ huí cún fàng wù pǐn。','Ra quầy phục vụ ở tầng một, báo tên và đặc điểm đồ vật là lấy lại được ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L720_07','V720','阮明',7,'我以后临时离开自习室，随身带走全部私人物品。','wǒ yǐ hòu lín shí lí kāi zì xí shì， suí shēn dài zǒu quán bù sī rén wù pǐn。','Sau này em sẽ mang hết đồ cá nhân theo người mỗi khi rời phòng tự học tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT721','SSH3','图书馆电脑无法登录校园内网，求助值班管理员',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V721','SIT721','P1','suon_se','tuy_y',NULL,'校园内网会定期服务器维护，维护期间图书馆电脑无法访问校内论文数据库，属于常规网络维护安排。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_01','V721','阮明',1,'你好，图书馆台式机输入学号，一直登录不上校园内网啊。','nǐ hǎo， tú shū guǎn tái shì jī shū rù xué hào， yì zhí dēng lù bù shàng xiào yuán nèi wǎng a。','Chào anh, máy tính bàn ở thư viện em nhập mã số sinh viên vào mà cứ không đăng nhập được mạng nội bộ trường ấy.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_02','V721','管理员',2,'是不是校园网账号欠费停机，或者密码输入错误呢？','shì bú shì xiào yuán wǎng zhàng hào qiàn fèi tíng jī， huò zhě mì mǎ shū rù cuò wù ne？','Không biết có phải tài khoản mạng trường bị khóa do quá hạn, hay là gõ nhầm mật khẩu không?','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_03','V721','阮明',3,'昨天还正常登录查阅文献，没有修改过账号密码。','zuó tiān hái zhèng cháng dēng lù chá yuè wén xiàn， méi yǒu xiū gǎi guò zhàng hào mì mǎ。','Hôm qua em còn đăng nhập bình thường để tra tài liệu mà, em có sửa tài khoản mật khẩu gì đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_04','V721','管理员',4,'今天校内服务器临时维护，部分电脑网络不稳定。','jīn tiān xiào nèi fú wù qì lín shí wéi hù， bù fèn diàn nǎo wǎng luò bù wěn dìng。','Hôm nay máy chủ nội bộ trường đang bảo trì tạm thời, một số máy mạng không ổn định.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_05','V721','阮明',5,'那大概多久恢复内网访问，我需要查阅专业论文。','nà dà gài duō jiǔ huī fù nèi wǎng fǎng wèn， wǒ xū yào chá yuè zhuān yè lùn wén。','Vậy khoảng bao lâu nữa thì truy cập mạng nội bộ lại được, em cần tra luận văn chuyên ngành gấp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_06','V721','管理员',6,'预计四十分钟维护结束，你可以先用手机流量临时查资料。','yù jì sì shí fēn zhōng wéi hù jié shù， nǐ kě yǐ xiān yòng shǒu jī liú liàng lín shí chá zī liào。','Dự kiến bốn mươi phút nữa bảo trì xong, em cứ tạm dùng 4G điện thoại để tra tài liệu trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L721_07','V721','阮明',7,'我先等服务器维护完成，再使用电脑下载文献。','wǒ xiān děng fú wù qì wéi hù wán chéng， zài shǐ yòng diàn nǎo xià zài wén xiàn。','Em đợi máy chủ bảo trì xong rồi mới dùng máy tính để tải tài liệu vậy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT722','SSH3','借阅书籍超期，咨询罚款标准、补缴流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V722','SIT722','P1','that_bai_nhe','ban_chinh_thuc',NULL,'图书逾期罚金必须线下结清，未缴清罚款会永久限制图书借阅、数据库使用权限。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_01','V722','阮明',1,'老师，我借阅的两本专业书忘记续借，已经超期八天了。','lǎo shī， wǒ jiè yuè de liǎng běn zhuān yè shū wàng jì xù jiè， yǐ jīng chāo qī bā tiān le。','Thầy/cô ơi, hai cuốn sách chuyên ngành em mượn quên gia hạn mất rồi, đã trễ tám ngày rồi ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_02','V722','馆员王老师',2,'先把图书归还，系统自动核算每日逾期罚款金额。','xiān bǎ tú shū guī huán， xì tǒng zì dòng hé suàn měi rì yú qī fá kuǎn jīn é。','Em trả sách trước đã, hệ thống sẽ tự động tính tiền phạt trễ hạn theo từng ngày.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_03','V722','阮明',3,'两本书分开计算罚金，还是合并统一收取费用？','liǎng běn shū fēn kāi jì suàn fá jīn， hái shì hé bìng tǒng yī shōu qǔ fèi yòng？','Hai cuốn tính tiền phạt riêng, hay là gộp chung lại thu một lần ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_04','V722','馆员王老师',4,'每本单独计费，两本书八天一共十六元逾期罚金嘛。','měi běn dān dú jì fèi， liǎng běn shū bā tiān yī gòng shí liù yuán yú qī fá jīn ma。','Mỗi cuốn tính riêng, hai cuốn tám ngày tổng cộng là mười sáu tệ tiền phạt đó nha.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_05','V722','阮明',5,'罚金只能线下在图书馆服务台扫码缴纳，不能线上支付吗？','fá jīn zhǐ néng xiàn xià zài tú shū guǎn fú wù tái sǎo mǎ jiǎo nà， bù néng xiàn shàng zhī fù ma？','Tiền phạt chỉ có thể quét mã nộp trực tiếp ở quầy phục vụ thư viện thôi, không thanh toán online được ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_06','V722','馆员王老师',6,'仅支持线下现场缴费，缴清罚金才能恢复借阅权限。','jǐn zhī chí xiàn xià xiàn chǎng jiǎo fèi， jiǎo qīng fá jīn cái néng huī fù jiè yuè quán xiàn。','Chỉ nộp trực tiếp tại chỗ thôi, nộp phạt xong mới được khôi phục quyền mượn sách.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L722_07','V722','阮明',7,'我现在扫码缴纳罚金，之后一定记好续借日期。','wǒ xiàn zài sǎo mǎ jiǎo nà fá jīn， zhī hòu yí dìng jì hǎo xù jiè rì qī。','Vậy giờ em quét mã nộp phạt luôn, sau này em nhớ kỹ ngày gia hạn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT723','SSH3','图书馆打印复印设备卡纸，找工作人员维修',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V723','SIT723','P1','suon_se','tuy_y',NULL,'自助打印设备卡纸禁止用户自行拆机拉扯纸张，容易造成硬件损坏，需工作人员专业处理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_01','V723','阮明',1,'你好，自助复印机打印到一半卡纸，纸张卡在机器里面了。','nǐ hǎo， zì zhù fù yìn jī dǎ yìn dào yí bàn kǎ zhǐ， zhǐ zhāng kǎ zài jī qì lǐ miàn le。','Chào anh, máy photocopy tự động in được nửa chừng thì kẹt giấy, giấy kẹt cứng trong máy luôn rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_02','V723','运维工作人员',2,'别手动拉扯纸张，容易损坏打印机内部齿轮。','bié shǒu dòng lā chě zhǐ zhāng， róng yì sǔn huài dǎ yìn jī nèi bù chǐ lún。','Đừng dùng tay kéo giấy ra, dễ làm hỏng bánh răng bên trong máy in lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_03','V723','阮明',3,'我只是按了停止键，没有强行拽取卡住的打印纸。','wǒ zhǐ shì àn le tíng zhǐ jiàn， méi yǒu qiáng xíng zhuāi qǔ kǎ zhù de dǎ yìn zhǐ。','Em chỉ bấm nút dừng thôi, không có cố kéo tờ giấy bị kẹt ra đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_04','V723','运维工作人员',4,'我打开机盖取出卡纸，清理之后就能恢复打印啦。','wǒ dǎ kāi jī gài qǔ chū kǎ zhǐ， qīng lǐ zhī hòu jiù néng huī fù dǎ yìn la。','Để tôi mở nắp máy lấy giấy kẹt ra, dọn xong là in lại bình thường thôi mà.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_05','V723','阮明',5,'刚才已经扣取打印费用，卡纸没有完整出纸会返还余额吗？','gāng cái yǐ jīng kòu qǔ dǎ yìn fèi yòng， kǎ zhǐ méi yǒu wán zhěng chū zhǐ huì fǎn huán yú é ma？','Lúc nãy tiền in đã bị trừ rồi, kẹt giấy mà không ra giấy hoàn chỉnh thì có được hoàn lại tiền không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_06','V723','运维工作人员',6,'单次卡纸未出纸，系统自动退还本次打印扣费。','dān cì kǎ zhǐ wèi chū zhǐ， xì tǒng zì dòng tuì huán běn cì dǎ yìn kòu fèi。','Kẹt giấy mà không in ra được thì hệ thống tự động hoàn lại tiền lần in đó thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L723_07','V723','阮明',7,'麻烦您检修机器，我等下继续打印复习资料。','má fán nín jiǎn xiū jī qì， wǒ děng xià jì xù dǎ yìn fù xí zī liào。','Phiền anh kiểm tra sửa máy giúp em, lát nữa em in tiếp tài liệu ôn tập ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT724','SSH3','自习到闭馆时间，咨询夜间留校自习申请渠道',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V724','SIT724','P1','twist','ban_chinh_thuc',NULL,'图书馆夜间统一闭馆安保巡查，国内高校单独设置通宵自习教室满足期末备考学生需求。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_01','V724','阮明',1,'距离期末考还有两周，图书馆九点闭馆太早，想夜间留校自习。','jù lí qī mò kǎo hái yǒu liǎng zhōu， tú shū guǎn jiǔ diǎn bì guǎn tài zǎo， xiǎng yè jiān liú xiào zì xí。','Còn hai tuần nữa là thi cuối kỳ rồi, thư viện đóng cửa lúc chín giờ sớm quá, em muốn ở lại trường tự học ban đêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_02','V724','管理员',2,'图书馆晚间九点统一闭馆，不允许学生留在馆内过夜自习。','tú shū guǎn wǎn jiān jiǔ diǎn tǒng yī bì guǎn， bù yǔn xǔ xué shēng liú zài guǎn nèi guò yè zì xí。','Thư viện đóng cửa cố định lúc chín giờ tối, không cho phép sinh viên ở lại trong thư viện qua đêm để tự học.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_03','V724','阮明',3,'有没有专门通宵自习教室，或者申请延长图书馆开放时间？','yǒu méi yǒu zhuān mén tōng xiāo zì xí jiào shì， huò zhě shēn qǐng yán cháng tú shū guǎn kāi fàng shí jiān？','Vậy có phòng tự học thâu đêm riêng nào không, hay là có thể xin gia hạn giờ mở cửa thư viện không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_04','V724','管理员',4,'教学楼有两间通宵自习室，图书馆无延时开放审批通道嘛。','jiào xué lóu yǒu liǎng jiān tōng xiāo zì xí shì， tú shū guǎn wú yán shí kāi fàng shěn pī tōng dào ma。','Tòa nhà giảng đường có hai phòng tự học thâu đêm, còn thư viện thì không có kênh xin gia hạn giờ mở cửa đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_05','V724','阮明',5,'教学楼通宵教室晚上十一点之后还能正常开灯自习吗？','jiào xué lóu tōng xiāo jiào shì wǎn shàng shí yì diǎn zhī hòu hái néng zhèng cháng kāi dēng zì xí ma？','Phòng tự học thâu đêm ở tòa giảng đường sau mười một giờ đêm vẫn bật đèn học bình thường được chứ ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_06','V724','管理员',6,'全天供电，门禁可刷校园卡二十四小时自由进出。','quán tiān gōng diàn， mén jìn kě shuā xiào yuán kǎ èr shí sì xiǎo shí zì yóu jìn chū。','Có điện cả ngày, cửa ra vào quẹt thẻ sinh viên là ra vào tự do hai mươi bốn tiếng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L724_07','V724','阮明',7,'今晚开始转移到教学楼通宵教室复习备考。','jīn wǎn kāi shǐ zhuǎn yí dào jiào xué lóu tōng xiāo jiào shì fù xí bèi kǎo。','Vậy tối nay em chuyển sang phòng tự học thâu đêm ở tòa giảng đường để ôn thi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT725','SSH3','借阅外文专业参考书，咨询馆员查找馆藏方法',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V725','SIT725','P1','suon_se','ban_chinh_thuc',NULL,'高校图书馆外文藏书单独分区管理，为保护原版书籍，不开放学生自行入内取阅，由馆员统一调取。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_01','V725','阮明',1,'老师，我需要越南语原版专业参考书，不知道怎么检索馆藏。','lǎo shī， wǒ xū yào yuè nán yǔ yuán bǎn zhuān yè cān kǎo shū， bù zhī dào zěn me jiǎn suǒ guǎn cáng。','Thầy ơi, em cần tìm sách tham khảo chuyên ngành bản gốc tiếng Việt, mà không biết tra cứu sách trong thư viện kiểu gì.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_02','V725','馆员王老师',2,'图书馆检索系统左上角切换外文分类，输入语种关键词即可。','tú shū guǎn jiǎn suǒ xì tǒng zuǒ shàng jiǎo qiè huàn wài wén fēn lèi， shū rù yǔ zhǒng guān jiàn cí jí kě。','Ở góc trên bên trái hệ thống tra cứu của thư viện có mục chuyển sang phân loại sách ngoại văn, em chỉ cần nhập từ khóa ngôn ngữ vào là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_03','V725','阮明',3,'检索出来显示在三楼外文馆藏区，需要凭借阅证入内取书对吧？','jiǎn suǒ chū lái xiǎn shì zài sān lóu wài wén guǎn cáng qū， xū yào píng jiè yuè zhèng rù nèi qǔ shū duì ba？','Tra ra thì thấy sách nằm ở khu sách ngoại văn tầng ba, vậy em phải có thẻ mượn sách mới vào lấy được đúng không ạ?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_04','V725','馆员王老师',4,'外文图书区域不对外开放自由取书，报书名由我调取。','wài wén tú shū qū yù bú duì wài kāi fàng zì yóu qǔ shū， bào shū míng yóu wǒ diào qǔ。','Khu sách ngoại văn không mở cửa cho tự do vào lấy đâu, em báo tên sách để cô lấy giúp cho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_05','V725','阮明',5,'那我把书籍编号发给您，麻烦帮忙调取这本参考书。','nà wǒ bǎ shū jí biān hào fā gěi nín， má fán bāng máng diào qǔ zhè běn cān kǎo shū。','Vậy em gửi mã số sách cho cô nhé, phiền cô lấy giúp em cuốn sách tham khảo này.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_06','V725','馆员王老师',6,'十分钟内找到书籍，你在服务台等候领取。','shí fēn zhōng nèi zhǎo dào shū jí， nǐ zài fú wù tái děng hòu lǐng qǔ。','Trong vòng mười phút cô sẽ tìm được sách, em ra quầy phục vụ đợi lấy nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L725_07','V725','阮明',7,'好，我在这里等候，感谢协助查找外文藏书。','hǎo， wǒ zài zhè lǐ děng hòu， gǎn xiè xié zhù chá zhǎo wài wén cáng shū。','Dạ vâng, em đợi ở đây, cảm ơn cô đã giúp em tìm sách ngoại văn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT726','SSH4','办理校园统一公交优惠学生卡，提交证件材料',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V726','SIT726','P1','suon_se','ban_chinh_thuc',NULL,'国内在校学生可办理公交学生卡，市内通勤公交享受半价优惠，长途客运不参与学生折扣政策。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_01','V726','阮明',1,'老师您好，想办理公交学生优惠卡，出门乘坐公交半价乘车。','lǎo shī nín hǎo， xiǎng bàn lǐ gōng jiāo xué shēng yōu huì kǎ， chū mén chéng zuò gōng jiāo bàn jià chéng chē。','Chào thầy, em muốn làm thẻ ưu đãi xe buýt học sinh, để đi xe buýt được giảm nửa giá ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_02','V726','办事老师',2,'准备好护照、学生证、一寸证件照，填写办卡申请表哦。','zhǔn bèi hǎo hù zhào、 xué shēng zhèng、 yī cùn zhèng jiàn zhào， tián xiě bàn kǎ shēn qǐng biǎo ó。','Em chuẩn bị hộ chiếu, thẻ sinh viên, ảnh thẻ cỡ 3x4, rồi điền tờ đăng ký làm thẻ nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_03','V726','阮明',3,'办好公交卡，全市所有公交线路都能享受学生折扣吗？','bàn hǎo gōng jiāo kǎ， quán shì suǒ yǒu gōng jiāo xiàn lù dōu néng xiǎng shòu xué shēng zhé kòu ma？','Làm thẻ xe buýt xong thì tất cả các tuyến xe buýt trong thành phố đều được hưởng ưu đãi học sinh phải không thầy?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_04','V726','办事老师',4,'市内常规公交全部半价，长途城际公交不适用优惠。','shì nèi cháng guī gōng jiāo quán bù bàn jià， cháng tú chéng jì gōng jiāo bù shì yòng yōu huì。','Xe buýt thường trong nội thành thì được giảm nửa giá hết, còn xe buýt liên tỉnh đường dài thì không áp dụng ưu đãi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_05','V726','阮明',5,'公交卡丢失可以挂失转移余额，和校园饭卡规则一样？','gōng jiāo kǎ diū shī kě yǐ guà shī zhuǎn yí yú é， hé xiào yuán fàn kǎ guī zé yī yàng？','Nếu mất thẻ xe buýt thì báo mất và chuyển số dư được, giống quy định thẻ ăn của trường đúng không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_06','V726','办事老师',6,'没错，携带证件到服务中心挂失补办，余额完整保留。','méi cuò， xié dài zhèng jiàn dào fú wù zhōng xīn guà shī bǔ bàn， yú é wán zhěng bǎo liú。','Đúng vậy, em mang giấy tờ đến trung tâm dịch vụ báo mất và làm lại thẻ, số dư vẫn giữ nguyên đầy đủ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L726_07','V726','阮明',7,'我备齐材料，今天办理学生公交优惠卡。','wǒ bèi qí cái liào， jīn tiān bàn lǐ xué shēng gōng jiāo yōu huì kǎ。','Em chuẩn bị đủ giấy tờ rồi, hôm nay em làm thẻ ưu đãi xe buýt học sinh luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT727','SSH4','共享单车扫码失败、车辆故障，咨询换车流程',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V727','SIT727','P1','twist','tuy_y',NULL,'共享单车故障车辆免费换车，短时间内切换新车不重复收取起步费用，是平台通用售后规则。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_01','V727','阮明',1,'师傅，这辆单车扫码开锁一直失败，页面提示车辆故障啊。','shī fù， zhè liàng dān chē sǎo mǎ kāi suǒ yì zhí shī bài， yè miàn tí shì chē liàng gù zhàng a。','Anh ơi, chiếc xe đạp này em quét mã mở khóa mãi không được, màn hình báo xe bị hỏng.','AM05') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_02','V727','运维员',2,'故障车辆后台锁定无法解锁，直接在APP点更换车辆按钮。','gù zhàng chē liàng hòu tái suǒ dìng wú fǎ jiě suǒ， zhí jiē zài APP diǎn gēng huàn chē liàng àn niǔ。','Xe hỏng thì hệ thống đã khóa lại rồi, không mở khóa được đâu, em bấm nút đổi xe trên app là được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_03','V727','阮明',3,'换车会不会重复收取骑行起步费，两辆车分开计费吗？','huàn chē huì bú huì chóng fù shōu qǔ qí xíng qǐ bù fèi， liǎng liàng chē fēn kāi jì fèi ma？','Đổi xe như vậy có bị tính lại phí mở chuyến không, hai xe có tính tiền riêng không anh?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_04','V727','运维员',4,'故障换车十分钟内切换新车，不会二次扣费，自动取消订单嘛。','gù zhàng huàn chē shí fēn zhōng nèi qiè huàn xīn chē， bú huì èr cì kòu fèi， zì dòng qǔ xiāo dìng dān ma。','Đổi xe do lỗi trong vòng mười phút thì không bị tính phí lần hai đâu, đơn cũ tự động hủy mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_05','V727','阮明',5,'那我直接换旁边完好单车，不用手动结束当前订单？','nà wǒ zhí jiē huàn páng biān wán hǎo dān chē， bù yòng shǒu dòng jié shù dāng qián dìng dān？','Vậy em cứ đổi luôn sang chiếc xe bên cạnh còn tốt, không cần tự tay kết thúc chuyến đang mở à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_06','V727','运维员',6,'APP一键换车系统自动处理，不用额外操作订单。','APP yī jiàn huàn chē xì tǒng zì dòng chǔ lǐ， bù yòng é wài cāo zuò dìng dān。','App đổi xe một chạm là hệ thống tự xử lý hết, em không cần thao tác thêm gì với đơn cũ đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L727_07','V727','阮明',7,'我现在操作更换车辆，正常骑行前往教学楼。','wǒ xiàn zài cāo zuò gēng huàn chē liàng， zhèng cháng qí xíng qián wǎng jiào xué lóu。','Giờ em thao tác đổi xe đây, rồi đi bình thường lên nhà giảng đường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT728','SSH4','校内电动车限速规定，被安保提醒减速慢行',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V728','SIT728','P1','that_bai_nhe','tuy_y',NULL,'国内大学校园非机动车统一低速限速，保护步行学生安全，多次超速会暂扣车辆进行安全教育。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_01','V728','阮明',1,'保安大叔，怎么拦下我，是电动车行驶有违规地方吗？','bǎo ān dà shū， zěn me lán xià wǒ， shì diàn dòng chē háng shǐ yǒu wéi guī dì fāng ma？','Chú bảo vệ ơi, sao chú chặn cháu lại vậy, xe điện cháu chạy có gì sai quy định à?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_02','V728','安保大叔',2,'校内道路限速十五公里每小时，你车速过快存在安全隐患。','xiào nèi dào lù xiàn sù shí wǔ gōng lǐ měi xiǎo shí， nǐ chē sù guò kuài cún zài ān quán yǐn huàn。','Đường trong trường quy định tốc độ tối đa mười lăm cây số một giờ, cháu chạy nhanh quá là có nguy cơ mất an toàn đấy.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_03','V728','阮明',3,'我赶去上课没留意限速标识，没有注意控制骑行速度嘛。','wǒ gǎn qù shàng kè méi liú yì xiàn sù biāo shí， méi yǒu zhù yì kòng zhì qí xíng sù dù ma。','Cháu vội đi học nên không để ý biển báo giới hạn tốc độ, không chú ý giữ tốc độ chậm lại ấy mà.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_04','V728','安保大叔',4,'校园行人多，电动车超速容易撞到散步、赶路的学生。','xiào yuán xíng rén duō， diàn dòng chē chāo sù róng yì zhuàng dào sàn bù、 gǎn lù de xué shēng。','Trong trường người đi bộ đông, xe điện chạy quá tốc độ dễ tông phải học sinh đang dạo bộ hay đang vội đi đâu đó lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_05','V728','阮明',5,'第一次超速提醒，会不会扣除校园通行积分或者罚款？','dì yī cì chāo sù tí xǐng， huì bú huì kòu chú xiào yuán tōng xíng jī fēn huò zhě fá kuǎn？','Lần đầu bị nhắc chạy quá tốc độ thế này có bị trừ điểm ra vào trường hay bị phạt tiền không chú?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_06','V728','安保大叔',6,'首次口头警告，多次超速会暂扣电动车半天教育。','shǒu cì kǒu tóu jǐng gào， duō cì chāo sù huì zàn kòu diàn dòng chē bàn tiān jiào yù。','Lần đầu thì chỉ nhắc nhở bằng lời thôi, chạy quá tốc độ nhiều lần thì sẽ bị giữ xe điện nửa ngày để giáo dục.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L728_07','V728','阮明',7,'之后在校内骑行放慢车速，严格遵守限速规定。','zhī hòu zài xiào nèi qí xíng fàng màn chē sù， yán gé zūn shǒu xiàn sù guī dìng。','Từ giờ cháu sẽ đi xe chậm lại trong trường, tuân thủ nghiêm quy định giới hạn tốc độ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT729','SSH4','快递驿站取件忘记取件码，凭护照核对身份取件',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V729','SIT729','P1','suon_se','tuy_y',NULL,'快递驿站可凭实名有效证件核对身份取件，不止局限于短信取件码，方便遗失短信的顾客。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_01','V729','阮明',1,'你好，我网购的快递到驿站，但是手机弄丢取件短信码了。','nǐ hǎo， wǒ wǎng gòu de kuài dì dào yì zhàn， dàn shì shǒu jī nòng diū qǔ jiàn duǎn xìn mǎ le。','Chào chị, em có đơn hàng online gửi về bưu cục, nhưng em làm mất tin nhắn mã lấy hàng trong điện thoại rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_02','V729','驿站店员',2,'报你的收件姓名、手机号，出示有效证件就能核对包裹。','bào nǐ de shōu jiàn xìng míng、 shǒu jī hào， chū shì yǒu xiào zhèng jiàn jiù néng hé duì bāo guǒ。','Em đọc tên người nhận, số điện thoại, rồi xuất trình giấy tờ tùy thân hợp lệ là chị đối chiếu được ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_03','V729','阮明',3,'我出示留学生护照，上面有我的姓名拼音可以核对身份吗？','wǒ chū shì liú xué shēng hù zhào， shàng miàn yǒu wǒ de xìng míng pīn yīn kě yǐ hé duì shēn fèn ma？','Em xuất trình hộ chiếu du học sinh, trên đó có tên phiên âm của em, vậy có đối chiếu được không chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_04','V729','驿站店员',4,'可以，姓名、手机号匹配无误就能直接找出快递包裹。','kě yǐ， xìng míng、 shǒu jī hào pǐ pèi wú wù jiù néng zhí jiē zhǎo chū kuài dì bāo guǒ。','Được chứ, tên với số điện thoại khớp là chị tìm ra được kiện hàng của em ngay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_05','V729','阮明',5,'麻烦帮我查找今天送达的小件包裹，是学习文具。','má fán bāng wǒ chá zhǎo jīn tiān sòng dá de xiǎo jiàn bāo guǒ， shì xué xí wén jù。','Phiền chị tìm giúp em kiện hàng nhỏ gửi đến hôm nay, đồ dùng học tập ấy ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_06','V729','驿站店员',6,'查到了，这个快递，你核对包裹面单信息再拿走。','chá dào le， zhè ge kuài dì， nǐ hé duì bāo guǒ miàn dān xìn xī zài ná zǒu。','Tìm ra rồi đây, kiện hàng này, em kiểm tra lại thông tin trên phiếu gửi rồi lấy về nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L729_07','V729','阮明',7,'信息全部匹配，感谢不用取件码也能取件。','xìn xī quán bù pǐ pèi， gǎn xiè bù yòng qǔ jiàn mǎ yě néng qǔ jiàn。','Thông tin khớp hết rồi, cảm ơn chị đã cho em lấy hàng dù không nhớ mã ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT730','SSH4','大件快递无法上楼，和驿站协商送货上门服务',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V730','SIT730','P1','twist','ban_chinh_thuc',NULL,'校园快递驿站以自取为主，大件重物单独上门配送会收取少量配送服务费，用于补贴人工运力。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_01','V730','阮明',1,'我这个纸箱是被褥大件，楼梯没有电梯，自己搬不动上楼。','wǒ zhè ge zhǐ xiāng shì bèi rù dà jiàn， lóu tī méi yǒu diàn tī， zì jǐ bān bù dòng shàng lóu。','Thùng các tông này của em là chăn đệm cồng kềnh, cầu thang lại không có thang máy, tự em không khiêng lên được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_02','V730','驿站店员',2,'校园驿站规定小件自取，大件上门需要额外支付配送服务费。','xiào yuán yì zhàn guī dìng xiǎo jiàn zì qǔ， dà jiàn shàng mén xū yào é wài zhī fù pèi sòng fú wù fèi。','Theo quy định của bưu cục trong trường, hàng nhỏ thì tự lấy, còn hàng cồng kềnh muốn giao tận nơi thì phải trả thêm phí giao hàng.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_03','V730','阮明',3,'宿舍就在校内宿舍楼，距离驿站步行三分钟也要额外收费嘛？','sù shè jiù zài xiào nèi sù shè lóu， jù lí yì zhàn bù xíng sān fēn zhōng yě yào é wài shōu fèi ma？','Ký túc xá em ở ngay trong khuôn viên trường, đi bộ từ bưu cục có ba phút mà cũng phải trả thêm phí sao?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_04','V730','驿站店员',4,'配送人员批量派送楼栋，单独上门单件加收三元配送费嘛。','pèi sòng rén yuán pī liàng pài sòng lóu dòng， dān dú shàng mén dān jiàn jiā shōu sān yuán pèi sòng fèi ma。','Nhân viên giao hàng giao theo lô cho cả tòa nhà, còn giao riêng lẻ từng đơn thì tính thêm ba tệ phí giao hàng.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_05','V730','阮明',5,'那我今天下午有空，能不能傍晚统一顺路送货上门？','nà wǒ jīn tiān xià wǔ yǒu kòng， néng bù néng bàng wǎn tǒng yī shùn lù sòng huò shàng mén？','Vậy chiều nay em rảnh, có thể chiều tối gộp giao luôn tiện đường được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_06','V730','驿站店员',6,'傍晚六点批量配送，你留好宿舍房间号等候送货。','bàng wǎn liù diǎn pī liàng pèi sòng， nǐ liú hǎo sù shè fáng jiān hào děng hòu sòng huò。','Sáu giờ chiều bên em giao hàng theo lô, em nhớ để lại số phòng ký túc xá rồi đợi giao hàng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L730_07','V730','阮明',7,'我同意支付配送费，傍晚等工作人员送被褥上楼。','wǒ tóng yì zhī fù pèi sòng fèi， bàng wǎn děng gōng zuò rén yuán sòng bèi rù shàng lóu。','Em đồng ý trả phí giao hàng, chiều tối em đợi nhân viên mang chăn đệm lên phòng giúp em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT731','SSH4','咨询校园医务室就诊流程、医保报销范围',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V731','SIT731','P1','suon_se','ban_chinh_thuc',NULL,'国内高校统一购买大学生医保，校内医务室基础诊疗、常用药品可按比例报销，大幅降低就医开支。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_01','V731','阮明',1,'护士您好，轻微咳嗽不舒服，想咨询医务室就诊流程。','hù shì nín hǎo， qīng wēi ké sòu bù shū fú， xiǎng zī xún yī wù shì jiù zhěn liú chéng。','Chào cô y tá, em bị ho nhẹ khó chịu trong người, muốn hỏi quy trình khám ở phòng y tế trường.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_02','V731','护士',2,'携带校园医保凭证、学生证，一楼分诊台登记排队就诊哦。','xié dài xiào yuán yī bǎo píng zhèng、 xué shēng zhèng， yī lóu fēn zhěn tái dēng jì pái duì jiù zhěn ó。','Em mang theo thẻ bảo hiểm y tế của trường, thẻ sinh viên, rồi đăng ký xếp hàng ở bàn phân loại tầng một để khám nhé.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_03','V731','阮明',3,'校内医务室拿药可以直接医保报销，不用全额自费吗？','xiào nèi yī wù shì ná yào kě yǐ zhí jiē yī bǎo bào xiāo， bù yòng quán é zì fèi ma？','Lấy thuốc ở phòng y tế trong trường có được bảo hiểm y tế thanh toán luôn không, hay em phải trả toàn bộ tiền túi?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_04','V731','护士',4,'基础感冒、消炎药品报销七成，美容、滋补类药品不参与报销。','jī chǔ gǎn mào、 xiāo yán yào pǐn bào xiāo qī chéng， měi róng、 zī bǔ lèi yào pǐn bù cān yù bào xiāo。','Thuốc cảm cúm cơ bản, thuốc kháng viêm thì bảo hiểm chi trả bảy mươi phần trăm, còn thuốc làm đẹp, thuốc bổ thì không nằm trong diện thanh toán.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_05','V731','阮明',5,'就诊之后如果需要输液，也是同样报销比例对吗？','jiù zhěn zhī hòu rú guǒ xū yào shū yè， yě shì tóng yàng bào xiāo bǐ lì duì ma？','Sau khi khám nếu cần truyền dịch thì cũng được thanh toán theo tỷ lệ như vậy đúng không cô?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_06','V731','护士',6,'普通诊疗、输液均纳入医保报销，仅自费耗材除外。','pǔ tōng zhěn liáo、 shū yè jūn nà rù yī bǎo bào xiāo， jǐn zì fèi hào cái chú wài。','Khám bệnh thông thường và truyền dịch đều được đưa vào diện bảo hiểm chi trả, chỉ có vật tư tự chi trả là ngoại lệ thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L731_07','V731','阮明',7,'我带好证件，现在登记排队问诊拿药。','wǒ dài hǎo zhèng jiàn， xiàn zài dēng jì pái duì wèn zhěn ná yào。','Em mang đủ giấy tờ rồi, giờ em đi đăng ký xếp hàng khám và lấy thuốc đây ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT732','SSH5','宿舍线上缴纳水电费，系统缴费失败咨询后勤',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V732','SIT732','P1','twist','ban_chinh_thuc',NULL,'校园线上缴费系统夜间服务器负载高容易卡顿，水电欠费设有三天缓冲期，不会立刻断供。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_01','V732','阮明',1,'您好，线上小程序缴纳宿舍电费，提交支付一直提示缴费失败。','nín hǎo， xiàn shàng xiǎo chéng xù jiǎo nà sù shè diàn fèi， tí jiāo zhī fù yì zhí tí shì jiǎo fèi shī bài。','Chào chị, em đóng tiền điện ký túc xá qua mini app trên mạng, mà bấm thanh toán cứ báo lỗi đóng tiền không được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_02','V732','后勤客服',2,'核对宿舍房间编号，近期是否输入错误楼栋号导致匹配失败？','hé duì sù shè fáng jiān biān hào， jìn qī shì fǒu shū rù cuò wù lóu dòng hào dǎo zhì pǐ pèi shī bài？','Em kiểm tra lại số phòng ký túc xá xem, gần đây có nhập nhầm số tòa nhà nên không khớp được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_03','V732','阮明',3,'楼栋、房间号全部核对无误，银行卡扣款短信也没有收到嘛。','lóu dòng、 fáng jiān hào quán bù hé duì wú wù， yín háng kǎ kòu kuǎn duǎn xìn yě méi yǒu shōu dào ma。','Tòa nhà, số phòng em đối chiếu lại hết rồi, không sai đâu, mà tin nhắn trừ tiền từ thẻ ngân hàng cũng không nhận được luôn.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_04','V732','后勤客服',4,'小程序晚间服务器拥堵，夜间零点至早八点系统不稳定。','xiǎo chéng xù wǎn jiān fú wù qì yōng dǔ， yè jiān líng diǎn zhì zǎo bā diǎn xì tǒng bù wěn dìng。','Buổi tối máy chủ mini app hay bị nghẽn, từ nửa đêm đến tám giờ sáng hệ thống không ổn định lắm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_05','V732','阮明',5,'那我明天上午再重新提交缴费，不会产生停水断电吧？','nà wǒ míng tiān shàng wǔ zài chóng xīn tí jiāo jiǎo fèi， bú huì chǎn shēng tíng shuǐ duàn diàn ba？','Vậy sáng mai em nộp lại tiền, chắc không bị cắt nước cắt điện chứ chị?','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_06','V732','后勤客服',6,'宿舍水电欠费缓冲三天，三天内缴费不会切断供应。','sù shè shuǐ diàn qiàn fèi huǎn chōng sān tiān， sān tiān nèi jiǎo fèi bú huì qiē duàn gōng yìng。','Tiền điện nước ký túc xá có thời gian gia hạn ba ngày, trong ba ngày đóng tiền thì không bị cắt cung cấp đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L732_07','V732','阮明',7,'明天一早完成缴费，避免宿舍水电临时关停。','míng tiān yī zǎo wán chéng jiǎo fèi， bì miǎn sù shè shuǐ diàn lín shí guān tíng。','Sáng mai em đóng tiền xong sớm luôn, để tránh bị cắt điện nước ký túc xá tạm thời.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT733','SSH5','校园校园网账号欠费断网，线上续费恢复网络',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V733','SIT733','P1','suon_se','tuy_y',NULL,'校园内网按月计费，欠费立刻断网，校内图书馆、论文数据库均依托校园网访问。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_01','V733','阮明',1,'电脑显示校园网欠费停机，网页视频、学习软件全都打不开。','diàn nǎo xiǎn shì xiào yuán wǎng qiàn fèi tíng jī， wǎng yè shì pín、 xué xí ruǎn jiàn quán dōu dǎ bù kāi。','Máy tính báo mạng trường bị nợ phí nên bị cắt kết nối, web, video, phần mềm học tập gì cũng không mở được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_02','V733','小林',2,'打开校园网小程序，输入学号就能线上充值续费啦。','dǎ kāi xiào yuán wǎng xiǎo chéng xù， shū rù xué hào jiù néng xiàn shàng chōng zhí xù fèi la。','Cậu mở app mạng trường lên, nhập mã số sinh viên vào là nạp tiền gia hạn online được ngay.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_03','V733','阮明',3,'包月套餐三十元，充值之后是立刻恢复网络吗？','bāo yuè tào cān sān shí yuán， chōng zhí zhī hòu shì lì kè huī fù wǎng luò ma？','Gói cước tháng ba mươi tệ, nạp xong là mạng có lại liền hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_04','V733','小林',4,'充值成功十秒内自动联网，不用重启电脑路由器。','chōng zhí chéng gōng shí miǎo nèi zì dòng lián wǎng， bù yòng chóng qǐ diàn nǎo lù yóu qì。','Nạp thành công là trong vòng mười giây tự động có mạng lại, không cần khởi động lại máy tính hay router đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_05','V733','阮明',5,'要是忘记续费，断网之后校内论文数据库也没法访问？','yào shì wàng jì xù fèi， duàn wǎng zhī hòu xiào nèi lùn wén shù jù kù yě méi fǎ fǎng wèn？','Nếu lỡ quên gia hạn, mất mạng rồi thì thư viện luận văn nội bộ trong trường cũng không vào được luôn hả?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_06','V733','小林',6,'没错，内网文献库依赖校园网，断网完全无法登录查阅。','méi cuò， nèi wǎng wén xiàn kù yī lài xiào yuán wǎng， duàn wǎng wán quán wú fǎ dēng lù chá yuè。','Đúng vậy đó, kho tài liệu nội bộ phụ thuộc vào mạng trường, mất mạng là chịu, không đăng nhập tra cứu được đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L733_07','V733','阮明',7,'我现在线上充值续费，恢复网络继续写作业。','wǒ xiàn zài xiàn shàng chōng zhí xù fèi， huī fù wǎng luò jì xù xiě zuò yè。','Giờ tớ nạp tiền gia hạn online luôn đây, có mạng lại rồi làm bài tiếp.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT734','SSH5','手机话费余额不足停机，便利店线下充值缴费',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V734','SIT734','P1','suon_se','tuy_y',NULL,'国内线下便利店可办理手机话费充值，适合线上支付故障、手机停机无法收验证码的情况。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_01','V734','阮明',1,'你好，手机停机没法收短信，能不能线下充值话费？','nǐ hǎo， shǒu jī tíng jī méi fǎ shōu duǎn xìn， néng bù néng xiàn xià chōng zhí huà fèi？','Chào chị, điện thoại em bị khóa máy không nhận được tin nhắn, chị cho em nạp tiền trực tiếp ở đây được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_02','V734','便利店店员',2,'支持五十、一百面额线下充值，输入手机号就能充值哈。','zhī chí wǔ shí、 yì bǎi miàn é xiàn xià chōng zhí， shū rù shǒu jī hào jiù néng chōng zhí hā。','Chỗ chị nhận nạp mệnh giá năm mươi, một trăm trực tiếp, cứ đọc số điện thoại là nạp được liền nha.','AM06') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_03','V734','阮明',3,'充值成功之后，多久手机能恢复通话、短信功能？','chōng zhí chéng gōng zhī hòu， duō jiǔ shǒu jī néng huī fù tōng huà、 duǎn xìn gōng néng？','Nạp xong thì bao lâu máy mới gọi được, nhắn tin lại được vậy chị?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_04','V734','便利店店员',4,'充值到账两分钟内自动复机，不用重启手机。','chōng zhí dào zhàng liǎng fēn zhōng nèi zì dòng fù jī， bù yòng chóng qǐ shǒu jī。','Tiền vào tài khoản là trong hai phút tự động mở máy lại, không cần khởi động lại điện thoại đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_05','V734','阮明',5,'那充值一百元，报我的手机号码给你。','nà chōng zhí yì bǎi yuán， bào wǒ de shǒu jī hào mǎ gěi nǐ。','Vậy chị nạp cho em một trăm, em đọc số điện thoại cho chị nha.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_06','V734','便利店店员',6,'充值完成，手机很快就能恢复正常通讯。','chōng zhí wán chéng， shǒu jī hěn kuài jiù néng huī fù zhèng cháng tōng xùn。','Nạp xong rồi đó, máy sẽ nhanh chóng liên lạc bình thường trở lại thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L734_07','V734','阮明',7,'太好了，终于可以联系家人和同学。','tài hǎo le， zhōng yú kě yǐ lián xì jiā rén hé tóng xué。','Tuyệt quá, cuối cùng cũng liên lạc được với gia đình với bạn học rồi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT735','SSH5','干洗店送洗衣物，询问污渍清洗、取件时效',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V735','SIT735','P1','twist','tuy_y',NULL,'重度油污、陈年污渍无法保证完全洗净，干洗店会根据清洗效果调整收费，提前告知顾客预期。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_01','V735','阮明',1,'你好，这件外套沾了油污，送过来干洗能完全洗掉污渍吗？','nǐ hǎo， zhè jiàn wài tào zhān le yóu wū， sòng guò lái gān xǐ néng wán quán xǐ diào wū zì ma？','Chào anh, cái áo khoác này dính dầu mỡ, đem giặt khô ở đây có sạch hết được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_02','V735','干洗店员',2,'大面积油污需要特殊去渍剂，不一定能彻底清除干净。','dà miàn jī yóu wū xū yào tè shū qù zì jì， bù yí dìng néng chè dǐ qīng chú gān jìng。','Vết dầu loang diện rộng như này cần dùng chất tẩy chuyên dụng, chưa chắc đã sạch hoàn toàn đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_03','V735','阮明',3,'要是洗完还有残留油污，会收取全套干洗费用嘛？','yào shì xǐ wán hái yǒu cán liú yóu wū， huì shōu qǔ quán tào gān xǐ fèi yòng ma？','Vậy nếu giặt xong mà vẫn còn dính dầu, tiệm có tính đủ tiền giặt khô không ạ?','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_04','V735','干洗店员',4,'尽力清洗，无法去除重度污渍仅收取基础洗护半价嘛。','jìn lì qīng xǐ， wú fǎ qù chú zhòng dù wū zì jǐn shōu qǔ jī chǔ xǐ hù bàn jià ma。','Bên anh sẽ cố hết sức để giặt, nếu vết bẩn nặng quá không tẩy được thì chỉ tính nửa giá giặt cơ bản thôi.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_05','V735','阮明',5,'正常洗护多久可以取件，三天后过来取来得及吗？','zhèng cháng xǐ hù duō jiǔ kě yǐ qǔ jiàn， sān tiān hòu guò lái qǔ lái de jí ma？','Giặt bình thường thì mất mấy ngày lấy được, ba ngày sau em quay lại lấy có kịp không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_06','V735','干洗店员',6,'标准洗护两天完工，三天来取完全没有问题。','biāo zhǔn xǐ hù liǎng tiān wán gōng， sān tiān lái qǔ wán quán méi yǒu wèn tí。','Giặt tiêu chuẩn hai ngày là xong rồi, ba ngày sau lấy hoàn toàn thoải mái.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L735_07','V735','阮明',7,'那我把外套留在店里，后天下午前来取衣服。','nà wǒ bǎ wài tào liú zài diàn lǐ， hòu tiān xià wǔ qián lái qǔ yī fú。','Vậy em để áo lại tiệm nha, chiều mốt em quay lại lấy áo.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT736','SSH5','上门保洁预约，和保洁阿姨确认清洁范围与时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V736','SIT736','P1','suon_se','ban_chinh_thuc',NULL,'上门保洁分基础清扫、深度清洁两类服务，厨房重度油污清理属于额外增值服务，需要增加时长与费用。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_01','V736','阮明',1,'阿姨，我预约两小时全屋保洁，跟您确认清洁区域吧。','ā yí， wǒ yù yuē liǎng xiǎo shí quán wū bǎo jié， gēn nín què rèn qīng jié qū yù ba。','Chị ơi, em đặt hai tiếng dọn dẹp toàn bộ nhà, để em xác nhận lại khu vực dọn với chị nhé.','AM07') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_02','V736','保洁阿姨',2,'客厅、卧室、卫生间常规清扫，厨房油污深度清洗需要额外加时。','kè tīng、 wò shì、 wèi shēng jiān cháng guī qīng sǎo， chú fáng yóu wū shēn dù qīng xǐ xū yào é wài jiā shí。','Phòng khách, phòng ngủ, nhà vệ sinh thì lau dọn bình thường, còn bếp mà muốn tẩy sạch dầu mỡ thì cần tính thêm giờ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_03','V736','阮明',3,'厨房简单擦拭台面即可，不用深度清理厚重油污。','chú fáng jiǎn dān cā shì tái miàn jí kě， bù yòng shēn dù qīng lǐ hòu zhòng yóu wū。','Bếp thì chỉ cần lau sơ mặt bàn thôi, không cần dọn kỹ hết lớp dầu mỡ dày đâu.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_04','V736','保洁阿姨',4,'两小时只做基础除尘拖地，不含重度厨房油污清理。','liǎng xiǎo shí zhǐ zuò jī chǔ chú chén tuō dì， bù hán zhòng dù chú fáng yóu wū qīng lǐ。','Hai tiếng thì chỉ làm phần lau bụi, lau nhà cơ bản thôi, không bao gồm dọn dầu mỡ nặng trong bếp ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_05','V736','阮明',5,'本周六上午九点上门，我提前把桌面杂物收纳好。','běn zhōu liù shàng wǔ jiǔ diǎn shàng mén， wǒ tí qián bǎ zhuō miàn zá wù shōu nà hǎo。','Thứ Bảy này chín giờ sáng chị đến nhé, em sẽ dọn đồ đạc trên bàn gọn gàng trước.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_06','V736','保洁阿姨',6,'到点准时上门，杂物收纳干净清洁效率更高。','dào diǎn zhǔn shí shàng mén， zá wù shōu nà gān jìng qīng jié xiào lǜ gèng gāo。','Vậy đúng giờ chị sẽ đến, đồ đạc gọn gàng thì dọn dẹp cũng nhanh và hiệu quả hơn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L736_07','V736','阮明',7,'我提前整理房间，方便阿姨快速完成全屋保洁。','wǒ tí qián zhěng lǐ fáng jiān， fāng biàn ā yí kuài sù wán chéng quán wū bǎo jié。','Em sẽ dọn phòng trước, để chị tiện làm sạch cả nhà cho nhanh.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT737','SSH6','报名校园羽毛球社团，咨询会费、活动固定时间',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V737','SIT737','P1','suon_se','tuy_y',NULL,'国内高校学生社团会费低廉，仅用于活动耗材、场地租赁，定期开展免费校内文体活动。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_01','V737','阮明',1,'学长，我想加入羽毛球社团，请问入社需要缴纳会费吗？','xué zhǎng， wǒ xiǎng jiā rù yǔ máo qiú shè tuán， qǐng wèn rù shè xū yào jiǎo nà huì fèi ma？','Anh ơi, em muốn tham gia câu lạc bộ cầu lông, vào câu lạc bộ có phải đóng hội phí không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_02','V737','学长',2,'一年二十元会费，全部用于采购羽毛球、场地租赁哦。','yī nián èr shí yuán huì fèi， quán bù yòng yú cǎi gòu yǔ máo qiú、 chǎng dì zū lìn ó。','Một năm hội phí hai mươi tệ, dùng hết để mua cầu lông với thuê sân đó.','AM03') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_03','V737','阮明',3,'社团固定活动周几开展，是校内体育馆场地吗？','shè tuán gù dìng huó dòng zhōu jǐ kāi zhǎn， shì xiào nèi tǐ yù guǎn chǎng dì ma？','Câu lạc bộ sinh hoạt cố định vào thứ mấy vậy anh, có phải ở nhà thi đấu trong trường không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_04','V737','学长',4,'每周四傍晚六点到八点，校内羽毛球馆专属场地。','měi zhōu sì bàng wǎn liù diǎn dào bā diǎn， xiào nèi yǔ máo qiú guǎn zhuān shǔ chǎng dì。','Mỗi tối thứ Năm từ sáu đến tám giờ, ở nhà thi đấu cầu lông riêng trong trường luôn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_05','V737','阮明',5,'没有自带球拍，社团可以临时借用训练球拍吗？','méi yǒu zì dài qiú pāi， shè tuán kě yǐ lín shí jiè yòng xùn liàn qiú pāi ma？','Em không có vợt riêng, câu lạc bộ có cho mượn vợt tập tạm thời không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_06','V737','学长',6,'新人可免费借用公用球拍，长期参与建议自备球拍。','xīn rén kě miǎn fèi jiè yòng gōng yòng qiú pāi， cháng qī cān yù jiàn yì zì bèi qiú pāi。','Thành viên mới thì được mượn vợt chung miễn phí, còn tham gia lâu dài thì nên tự sắm vợt riêng nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L737_07','V737','阮明',7,'我今天缴纳会费入社，周四准时参加社团活动。','wǒ jīn tiān jiǎo nà huì fèi rù shè， zhōu sì zhǔn shí cān jiā shè tuán huó dòng。','Vậy hôm nay em đóng hội phí vào câu lạc bộ luôn, thứ Năm em sẽ đến sinh hoạt đúng giờ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT738','SSH6','校园操场运动扭伤，前往医务室简单处理伤口',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V738','SIT738','P1','twist','ban_chinh_thuc',NULL,'校内医务室跌打损伤、消炎外敷药品均可医保报销，运动受伤可免费冷敷理疗处理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_01','V738','阮明',1,'护士，操场跑步崴到脚踝，现在肿胀疼痛没法正常走路。','hù shì， cāo chǎng pǎo bù wǎi dào jiǎo huái， xiàn zài zhǒng zhàng téng tòng méi fǎ zhèng cháng zǒu lù。','Cô ơi, em chạy ở sân vận động bị trẹo mắt cá chân, giờ sưng đau không đi lại bình thường được.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_02','V738','护士',2,'先坐下抬高腿部冷敷消肿，我给你开外用消炎药膏。','xiān zuò xià tái gāo tuǐ bù lěng fū xiāo zhǒng， wǒ gěi nǐ kāi wài yòng xiāo yán yào gāo。','Em ngồi xuống, kê cao chân lên chườm lạnh cho giảm sưng, cô sẽ kê cho em thuốc mỡ kháng viêm bôi ngoài.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_03','V738','阮明',3,'冷敷需要持续多久，今晚还能正常下床行走吗？','lěng fū xū yào chí xù duō jiǔ， jīn wǎn hái néng zhèng cháng xià chuáng xíng zǒu ma？','Chườm lạnh cần bao lâu vậy cô, tối nay em có xuống giường đi lại bình thường được không ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_04','V738','护士',4,'连续冷敷二十分钟，三天之内尽量减少走路、剧烈运动嘛。','lián xù lěng fū èr shí fēn zhōng， sān tiān zhī nèi jǐn liàng jiǎn shǎo zǒu lù、 jù liè yùn dòng ma。','Chườm lạnh liên tục hai mươi phút, trong ba ngày cố gắng hạn chế đi lại, vận động mạnh nhé.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_05','V738','阮明',5,'药膏医保可以报销吗，还是需要全额自费购买？','yào gāo yī bǎo kě yǐ bào xiāo ma， hái shì xū yào quán é zì fèi gòu mǎi？','Thuốc mỡ có được bảo hiểm y tế thanh toán không ạ, hay em phải tự trả toàn bộ tiền thuốc?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_06','V738','护士',6,'外用跌打药膏纳入学生医保，只需要自费三成费用。','wài yòng diē dǎ yào gāo nà rù xué shēng yī bǎo， zhǐ xū yào zì fèi sān chéng fèi yòng。','Thuốc mỡ trị bong gân được đưa vào bảo hiểm y tế sinh viên, em chỉ cần tự trả ba mươi phần trăm thôi.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L738_07','V738','阮明',7,'我拿药之后回宿舍静养，不再剧烈运动加重扭伤。','wǒ ná yào zhī hòu huí sù shè jìng yǎng， bù zài jù liè yùn dòng jiā zhòng niǔ shāng。','Em lấy thuốc xong sẽ về ký túc xá nghỉ ngơi, không vận động mạnh nữa kẻo trẹo nặng thêm.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT739','SSH6','咨询校园奖学金申请条件、提交材料截止日期',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V739','SIT739','P1','suon_se','chinh_thuc',NULL,'留学生奖学金对出勤率、期末分数有硬性门槛，逾期不接受补报，错过只能等待下一学年申报。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_01','V739','阮明',1,'老师您好，想咨询留学生校级奖学金的申请基础条件。','lǎo shī nín hǎo， xiǎng zī xún liú xué shēng xiào jí jiǎng xué jīn de shēn qǐng jī chǔ tiáo jiàn。','Chào thầy/cô, em muốn hỏi về điều kiện cơ bản để nộp đơn xin học bổng cấp trường dành cho lưu học sinh ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_02','V739','教务老师',2,'全年出勤率达标、期末平均分七十五分以上方可申报。','quán nián chū qín lǜ dá biāo、 qī mò píng jūn fēn qī shí wǔ fēn yǐ shàng fāng kě shēn bào。','Tỷ lệ chuyên cần cả năm phải đạt chuẩn, điểm trung bình học kỳ từ bảy mươi lăm điểm trở lên mới đủ điều kiện đăng ký.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_03','V739','阮明',3,'申请需要提交成绩单、在校证明，截止提交日期是哪天？','shēn qǐng xū yào tí jiāo chéng jì dān、 zài xiào zhèng míng， jié zhǐ tí jiāo rì qī shì nǎ tiān？','Hồ sơ cần nộp bảng điểm, giấy xác nhận đang học, vậy hạn chót nộp hồ sơ là ngày nào ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_04','V739','教务老师',4,'本月二十五号下午五点关闭申报通道，逾期不予受理。','běn yuè èr shí wǔ hào xià wǔ wǔ diǎn guān bì shēn bào tōng dào， yú qī bù yǔ shòu lǐ。','Cổng đăng ký sẽ đóng lúc năm giờ chiều ngày hai mươi lăm tháng này, nộp trễ sẽ không được xét ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_05','V739','阮明',5,'材料线上系统提交，还是纸质复印件线下上交学院？','cái liào xiàn shàng xì tǒng tí jiāo， hái shì zhǐ zhì fù yìn jiàn xiàn xià shàng jiāo xué yuàn？','Hồ sơ nộp qua hệ thống online, hay là nộp bản giấy photo trực tiếp cho khoa ạ?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_06','V739','教务老师',6,'线上填报信息，纸质材料线下送至国际学院办公室。','xiàn shàng tián bào xìn xī， zhǐ zhì cái liào xiàn xià sòng zhì guó jì xué yuàn bàn gōng shì。','Điền thông tin online, còn bản giấy thì nộp trực tiếp tại văn phòng học viện quốc tế nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L739_07','V739','阮明',7,'我这周整理好全部材料，提前完成奖学金申报。','wǒ zhè zhōu zhěng lǐ hǎo quán bù cái liào， tí qián wán chéng jiǎng xué jīn shēn bào。','Vậy tuần này em sẽ chuẩn bị đầy đủ hồ sơ, hoàn thành đăng ký học bổng sớm ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT740','SSH6','校内丢失水杯、雨伞，去失物招领处登记寻物',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V740','SIT740','P1','that_bai_nhe','tuy_y',NULL,'校园失物招领处仅短期保管遗失物品，超过一周无人认领会统一收纳，长期无人认领定期清理。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_01','V740','阮明',1,'你好，我昨天操场丢失黑色水杯、折叠雨伞，前来登记寻物。','nǐ hǎo， wǒ zuó tiān cāo chǎng diū shī hēi sè shuǐ bēi、 zhé dié yǔ sǎn， qián lái dēng jì xún wù。','Chào anh/chị, hôm qua em làm mất bình nước màu đen và cây dù gấp ở sân vận động, em đến đăng ký tìm đồ ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_02','V740','工作人员',2,'登记物品外观、丢失地点、你的联系方式，有人上交会通知你。','dēng jì wù pǐn wài guān、 diū shī dì diǎn、 nǐ de lián xì fāng shì， yǒu rén shàng jiāo huì tōng zhī nǐ。','Em đăng ký hình dạng đồ vật, chỗ mất, số điện thoại liên hệ của em, có ai nộp lên thì bên anh/chị sẽ báo cho em.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_03','V740','阮明',3,'水杯侧面印有越南文字标识，雨伞是深蓝色，特征很明显。','shuǐ bēi cè miàn yìn yǒu yuè nán wén zì biāo shí， yǔ sǎn shì shēn lán sè， tè zhēng hěn míng xiǎn。','Bình nước có in chữ tiếng Việt ở mặt bên, còn dù thì màu xanh navy, đặc điểm khá rõ ràng ạ.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_04','V740','工作人员',4,'今日上交失物清单没有匹配物品，大概率还未被捡拾上交嘛。','jīn rì shàng jiāo shī wù qīng dān méi yǒu pǐ pèi wù pǐn， dà gài lǜ hái wèi bèi jiǎn shí shàng jiāo ma。','Danh sách đồ thất lạc nộp lên hôm nay không khớp món nào cả, chắc là chưa ai nhặt được nộp lên đâu.','AM09') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_05','V740','阮明',5,'要是之后有人送到招领处，麻烦打电话通知我过来领取。','yào shì zhī hòu yǒu rén sòng dào zhāo lǐng chù， má fán dǎ diàn huà tōng zhī wǒ guò lái lǐng qǔ。','Nếu sau này có ai đem nộp lên, phiền anh/chị gọi điện báo em đến nhận nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_06','V740','工作人员',6,'登记信息留存一周，一周无人认领物品统一清理存放。','dēng jì xìn xī liú cún yī zhōu， yī zhōu wú rén rèn lǐng wù pǐn tǒng yī qīng lǐ cún fàng。','Thông tin đăng ký sẽ lưu lại một tuần, sau một tuần không ai nhận thì đồ sẽ được gom lại lưu kho.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L740_07','V740','阮明',7,'我三天后再来招领处询问，看看有没有捡到我的物品。','wǒ sān tiān hòu zài lái zhāo lǐng chù xún wèn， kàn kàn yǒu méi yǒu jiǎn dào wǒ de wù pǐn。','Ba ngày nữa em sẽ quay lại phòng tìm đồ hỏi thăm, xem có nhặt được đồ của em chưa.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT801','SHT1','向同班同学借课件PPT，拷贝到自己电脑复习',NULL,'B1') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V801','SIT801','P1','suon_se','tuy_y',NULL,'国内课堂老师大多会课后分享电子课件，同学之间互相转发课件、笔记是很普遍的互助学习习惯。') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_01','V801','阮明',1,'苏雯，昨天专业课老师的课件我忘记拷贝，能发我一份PPT吗？','sū wén， zuó tiān zhuān yè kè lǎo shī de kè jiàn wǒ wàng jì kǎo bèi， néng fā wǒ yī fèn PPT ma？','Tô Văn ơi, hôm qua mình quên copy slide bài giảng chuyên ngành của thầy, cậu gửi cho mình bản PPT được không?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_02','V801','苏雯',2,'没问题，我把完整课件打包，微信文件传输发给你就行啦。','méi wèn tí， wǒ bǎ wán zhěng kè jiàn dǎ bāo， wēi xìn wén jiàn chuán shū fā gěi nǐ jiù xíng la。','Không vấn đề gì, mình đóng gói cả bộ slide lại rồi gửi qua truyền file WeChat cho cậu là được nè.','AM02') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_03','V801','阮明',3,'文件内存很大，微信会不会压缩模糊里面的表格内容？','wén jiàn nèi cún hěn dà， wēi xìn huì bú huì yā suō mó hú lǐ miàn de biǎo gé nèi róng？','File nặng vậy WeChat có nén làm mờ mấy cái bảng biểu trong đó không ta?',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_04','V801','苏雯',4,'我发原文件不压缩，要是打不开我再分享网盘链接给你呢。','wǒ fā yuán wén jiàn bù yā suō， yào shì dǎ bù kāi wǒ zài fēn xiǎng wǎng pán liàn jiē gěi nǐ ne。','Mình gửi file gốc không nén đâu, nếu mở không được thì mình chia sẻ link ổ đĩa mạng cho cậu nhé.','AM04') ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_05','V801','阮明',5,'太好了，我今晚对照课件梳理今天课堂没听懂的知识点。','tài hǎo le， wǒ jīn wǎn duì zhào kè jiàn shū lǐ jīn tiān kè táng méi tīng dǒng de zhī shí diǎn。','Tuyệt quá, tối nay mình đối chiếu slide để rà lại mấy chỗ chưa hiểu trên lớp hôm nay.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_06','V801','苏雯',6,'课件里标注了期末重点，复习的时候可以优先看标红部分。','kè jiàn lǐ biāo zhù le qī mò zhòng diǎn， fù xí de shí hòu kě yǐ yōu xiān kàn biāo hóng bù fèn。','Trong slide có đánh dấu trọng tâm cuối kỳ đó, lúc ôn thì ưu tiên xem phần bôi đỏ trước nhé.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L801_07','V801','阮明',7,'太感谢你，有完整课件复习会轻松很多。','tài gǎn xiè nǐ， yǒu wán zhěng kè jiàn fù xí huì qīng sōng hěn duō。','Cảm ơn cậu nhiều lắm, có slide đầy đủ thì ôn bài nhẹ nhàng hơn hẳn.',NULL) ON CONFLICT DO NOTHING;
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT802','SHT1','询问老师课堂录音是否允许，方便课后复盘知识点',NULL,'B1') ON CONFLICT DO NOTHING;
